Change(genesis='e44b01205cdace6f30ebc3c48eee515a5e1ef4d70aae9a18b591ba5f45a131a9', deps=('a2ef03be1a839a2e73fe54fb9672f79fc9c6951e4415399d90af094a5d81bb73',), event=Authored(todo='lazy-content-by-hash', at=datetime(2026, 10, 17, 10, 4, 41, 231240), actor='maintainer', kind='todo', created=datetime(2026, 10, 17, 10, 4, 41, 231240), body="sync a store's skeleton eagerly and fetch its content lazily, by hash", spec=None, rationale=(), category='', waiting_on='', detail="An object carries its content inline, so a replica cannot take the shape of a history without all of its bytes. Split each object into a small skeleton (its parents, its header, the hash of its content) and its content, addressed by its own hash. A replica then syncs the skeleton eagerly, fetches content on demand, and keeps it forever: a hash's bytes never change, so a server can serve it as immutable and a client never invalidates it. Prefetch by recency covers the common case. Folds stay memoised per node, so a new event costs one node. This builds on event-header-body-split. Price 75: an application with large stores pays for every byte today, even to read one part.", source=None, subtodos=(), notes=(), note=''))